class App:
    def __init__(self):
        self.routes = {}
    def get(self, path):
        def decorate(func):
            self.routes[path] = func.__name__
            return func
        return decorate

app = App()

@app.get("/api/search")
def search():
    return {"ok": True}

registered = app.routes["/api/search"]

